(()=>{
 const SITE='https://carevia.triple-labs-8416.chatgpt.site/';
 const labels={'Treatments':'Services','Results':'How it works','Fees':'Pricing','About':'Doctors','Journal':'Help','Explore care':'Explore care','See the prices':'See the prices'};
 const hrefs={'./treatments':'#treatments','/treatments':'#treatments','./results':'#first-visit','/results':'#first-visit','./fees':'#carevia-pricing','/fees':'#carevia-pricing','./about':'#dentists','/about':'#dentists','./journal':'#questions','/journal':'#questions'};
 function update(){
  const headings={'section[data-framer-name="Services"] h2':'What we do, seen clearly.','section[data-framer-name="First visit"] h2':'Care in three simple steps.','section[data-framer-name="Doctors"] h2':'Meet our doctors.'};
  for(const [selector,value] of Object.entries(headings)){let el=document.querySelector(selector);if(el&&el.textContent!==value)el.textContent=value}
  document.querySelectorAll('span').forEach(p=>{if(/^(Open now|Closed now)/.test(p.textContent))p.textContent='Secure video consultations'});
  document.querySelectorAll('a').forEach(a=>{if(a.textContent.includes('(503) 555-0148'))a.style.display='none';let t=a.textContent.trim(),v=labels[t];if(v&&t!==v){const walker=document.createTreeWalker(a,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){if(node.nodeValue.trim()===t){node.nodeValue=v;break}}}});
  document.querySelectorAll('[data-framer-name="Footer"] p').forEach(p=>{if(p.textContent==='Carevia, a Framer template by Ajoy')p.textContent='Alder template by Ajoy';if(p.textContent==='© 2026 Carevia Studio. All rights reserved.')p.textContent='© 2026 Carevia. All rights reserved.'});
  document.querySelectorAll('[data-framer-name="Services"] p').forEach(p=>{if(p.textContent.startsWith('Each panel clears as you scroll'))p.textContent='Choose the care that suits you. See the price before you book and meet a registered doctor by secure video.'});
  document.querySelectorAll('nav a').forEach(a=>{let t=a.textContent.trim(),v=labels[t];if(v&&a.children.length===0&&a.textContent!==v)a.textContent=v});
  document.querySelectorAll('a').forEach(a=>{let h=a.getAttribute('href')||'';let next=hrefs[h];if(next&&h!==next)a.setAttribute('href',next);else if((/^\.\/(dentists|legal|treatments|results|journal)\//.test(h)||/^\/(dentists|legal|treatments|results|journal)\//.test(h))&&h!==SITE)a.setAttribute('href',SITE);else if(h.startsWith('tel:')&&h!=='tel:112')a.setAttribute('href',SITE);});
  document.querySelectorAll('a').forEach(a=>{let t=a.textContent.trim();if(t==='Explore care'&&a.getAttribute('href')!==SITE)a.setAttribute('href',SITE);if(t==='See the prices'&&a.getAttribute('href')!=='#carevia-pricing')a.setAttribute('href','#carevia-pricing');});
 }
 window.addEventListener('click',e=>{const a=e.target.closest('a');if(!a)return;let h=a.getAttribute('href')||'';if(h.startsWith('#')){let target=document.getElementById(h.slice(1));if(target){e.preventDefault();e.stopPropagation();target.scrollIntoView({behavior:'smooth'})}}else if(h===SITE){e.preventDefault();e.stopPropagation();window.location.href=SITE}},true);
 function addContent(){
  const idea=document.querySelector('section[data-framer-name="The idea"]');if(idea&&idea.style.visibility!=="visible")idea.style.visibility="visible";
  const q=document.querySelector('section[data-framer-name="Questions"]');if(q&&!document.getElementById('carevia-added')){let el=document.createElement('div');el.id='carevia-added';el.innerHTML=`<div class="carevia-faq"><details><summary>Who can use Carevia?</summary><p>Adults aged 18 and over can create an account. Parents and legal guardians can add children and other dependants and book on their behalf. You need to be in a supported country during your visit.</p></details><details><summary>Which countries are supported?</summary><p>Availability depends on your country and your doctor’s registration. Confirm availability before booking.</p></details><details><summary>Can I get a prescription or certificate?</summary><p>A doctor may issue prescriptions, certificates and referrals when clinically appropriate, after assessing you during your consultation.</p></details><details><summary>What happens if the video connection fails?</summary><p>You can rebook for free. Contact support for help arranging another consultation.</p></details><details><summary>How are recordings handled?</summary><p>Your written summary and issued documents are saved in your account. Contact support before your visit for details about audio or video recording.</p></details></div><div class="carevia-alert"><strong>Need urgent help?</strong>Carevia is not an emergency service. In an emergency, <a href="tel:112">call 112</a> or go to your nearest emergency department.</div>`;q.after(el)}
  const doctors=document.querySelector('section[data-framer-name="Doctors"]');if(doctors&&!document.getElementById('carevia-pricing')){let el=document.createElement('section');el.className='carevia-price';el.id='carevia-pricing';el.innerHTML='<h2>Clear prices. Nothing hidden.</h2><div><span>General consultation</span><strong>€45</strong></div><div><span>Adult psychology</span><strong>€65</strong></div><div><span>Prescription renewal</span><strong>€35</strong></div><div><span>Sick leave certificate</span><strong>€39</strong></div><div><span>Specialist consultation</span><strong>From €85</strong></div><small>Example prices, confirmed per country before launch. Prescriptions and certificates are issued when clinically appropriate.</small>';doctors.before(el)}
  update();
 }
 window.addEventListener('load',()=>{setTimeout(()=>{addContent();new MutationObserver(addContent).observe(document.body,{childList:true,subtree:true,characterData:true});},2200)});
})();
